const NMAX=(()=>{let m=0;for(const k in NDICT)if(k.length>m)m=k.length;for(const k of NSTOP)if(k.length>m)m=k.length;return m})();
Object.assign(NDICT,{"ທຸ່ມ":"밤 시각: 1툼=7시, 2툼=8시 … 5툼=11시","ຄ່ອຍ":"별로·잘(부정문에서)","ໃບ":"~장·~개(종이 등)"});
function notesOf(lo,w){const hw=(w||"").replace(/…/g,"").trim();const seen=new Set(),out=[];
  /* split each Lao run into known words: fewest uncovered letters first, then fewest pieces, then evenest pieces (ປີນີ້ = ປີ+ນີ້, not ປີນ+ີ້) */
  const isW=t=>NDICT[t]!==undefined||NSTOP.has(t);const bad=/^[\u0EB1\u0EB4-\u0EBC\u0EC8-\u0ECD]/;
  for(const run of lo.match(/[\u0E80-\u0EFF]+/g)||[]){const n=run.length,dp=[[0,0,-1,0,0]];
    for(let e=1;e<=n;e++){let best=[dp[e-1][0]+1,dp[e-1][1]+1,e-1,0,dp[e-1][4]+1];
      for(let b=Math.max(0,e-NMAX);b<e-1;b++){const t=run.slice(b,e);if(!isW(t)||bad.test(t)||(e<n&&bad.test(run[e]))||(b>0&&/[\u0EC0-\u0EC4]/.test(run[b-1])))continue;const c=[dp[b][0],dp[b][1]+1,b,1,dp[b][4]+(e-b)*(e-b)];if(c[0]<best[0]||(c[0]===best[0]&&(c[1]<best[1]||(c[1]===best[1]&&c[4]<best[4]))))best=c}
      dp[e]=best}
    const toks=[];for(let e=n;e>0;e=dp[e][2])if(dp[e][3])toks.unshift(run.slice(dp[e][2],e));
    for(const t of toks)if(NDICT[t]!==undefined&&t.length>2&&!seen.has(t)&&!(hw&&(hw.includes(t)||t.includes(hw)))){seen.add(t);out.push(t)}}
  /* ທຸ່ມ (night hours) always gets a note, even on its own card */if(lo.includes("ທຸ່ມ")&&!out.includes("ທຸ່ມ")){out.unshift("ທຸ່ມ")}
  if(out.length>3){const fix=out.filter(t=>t==="ທຸ່ມ");const keep=new Set(fix.concat(out.filter(t=>t!=="ທຸ່ມ").sort((a,b)=>(NFREQ[a]||0)-(NFREQ[b]||0)).slice(0,3-fix.length)));return out.filter(t=>keep.has(t))}return out}
function noteMark(html,ws){if(!ws.length)return html;const parts=html.split(/(<mark>[\s\S]*?<\/mark>|<[^>]+>)/);const left=new Set(ws);
  return parts.map(p=>{if(p.startsWith("<"))return p;for(const t of [...left].sort((a,b)=>b.length-a.length)){const e=esc(t);const k=p.indexOf(e);if(k>=0){p=p.slice(0,k)+'<span class="nw">'+e+'<sup>※</sup></span>'+p.slice(k+e.length);left.delete(t);
    p=p.replace(/(<span class="nw">[\s\S]*?<\/span>)/g,m=>m)}}return p}).join("")}

;
