function renderSearch(){
  const q=S.q.trim().toLowerCase();const hits=[];
  for(const [id,b] of Object.entries(B))for(const w of b.w)if(w[0].includes(q)||w[2].replace(/\s/g,"").includes(q.replace(/\s/g,""))||w[3].includes(q))hits.push([id,w]);
  const subOf=id=>Object.values(SUBS).find(s=>s.b.includes(id));
  $("#band").innerHTML=`<div><span class="gname">SEARCH</span><h2>“${esc(S.q.trim())}” 검색 결과<small>${hits.length}개 단어 · 누르면 해당 묶음의 문장 연습으로 이동</small></h2></div>`;
  $("#controls").hidden=true;$("#app").dataset.g=S.part;
  $("#view").innerHTML=hits.length?`<div class="results">${hits.slice(0,100).map(([id,w])=>{const s=subOf(id);return `<button class="hit" data-g="${s.part}" data-goto="${id}"><span class="w">${esc(w[0])}</span><span class="m">${esc(w[2])} · ${esc(w[3])}</span><span class="where">${id} · ${esc(s.name)}</span></button>`}).join("")}</div>`:`<p class="empty">찾는 단어가 없어요. 한국어 뜻이나 독음으로도 검색해 보세요.</p>`;
}
